/**
 * 当前人设包文字资料的专用读取工具（alpha.17 审查：SKILL.md 只给附件名，
 * 模型没有直接打开 references 的入口）。
 *
 * 只做两件事：列索引、按索引里的相对路径读文本。路径白名单来自加载器自己的
 * 文件清单——不把路径拼接后的任意读取交给模型；二进制、超限文件直接拒绝。
 */
const MAX_TEXT_BYTES = 256 * 1024;

/** 模型可见的工具名。 */
export const PERSONA_TEXT_TOOLS = Object.freeze({
  list: 'list_persona_references',
  read: 'read_persona_reference',
});

/** 把任意异常收敛成一句模型能看懂、又不泄漏栈的错误。 */
function messageOf(value) {
  return value instanceof Error ? value.message : String(value);
}

/** 解析人设 id：省略取当前人设，传空串/非字符串等同省略。 */
function personaIdOf(core, loaderOf, requested) {
  if (typeof requested === 'string' && requested.trim() !== '') return requested.trim();
  const loader = loaderOf?.();
  return loader?.activeId?.() ?? undefined;
}

/** 在白名单里找文件；找不到或超限都拒绝。 */
function findEntry(entries, path) {
  if (typeof path !== 'string' || path.trim() === '') return undefined;
  const wanted = path.trim().replace(/^\.\//, '');
  return entries.find(entry => entry.path === wanted);
}

/** 把两条工具注册到宿主的 tools 服务；缺席时静默跳过，不拖垮人格插件。 */
export function registerPersonaTextTools(ctx, core, loaderOf, log) {
  ctx.inject(['tools'], toolCtx => {
    const tools = toolCtx.tools ?? ctx.get('tools');
    if (tools === undefined || tools.register === undefined) return;

    const resolve = requested => {
      const id = personaIdOf(core, loaderOf, requested);
      if (id === undefined) return { error: '当前没有人设，先在人设页选择一个角色' };
      return { id, entries: core.references(id) };
    };

    const disposeList = tools.register({
      name: PERSONA_TEXT_TOOLS.list,
      description: '列出当前人设包内的文字附件（reference）路径、说明与大小。需要读附件正文时先用它确认路径。',
      parameters: {
        type: 'object',
        properties: {
          personaId: { type: 'string', description: '人设 id；省略表示当前人设' },
        },
        additionalProperties: false,
      },
      output: {
        schema: {
          type: 'object',
          properties: {
            personaId: { type: 'string' },
            references: {
              type: 'array',
              items: {
                type: 'object',
                properties: {
                  path: { type: 'string' },
                  doc: { type: 'string' },
                  bytes: { type: 'number' },
                },
                required: ['path', 'doc', 'bytes'],
              },
            },
          },
          required: ['personaId', 'references'],
        },
        render: (_args, value) => value,
      },
      execute: args => {
        const result = resolve(args?.personaId);
        if (result.error !== undefined) return { error: result.error };
        return {
          personaId: result.id,
          references: result.entries.map(entry => ({
            path: entry.path,
            doc: entry.doc ?? '',
            bytes: entry.bytes ?? 0,
          })),
        };
      },
    });

    const disposeRead = tools.register({
      name: PERSONA_TEXT_TOOLS.read,
      description: '按 list_persona_references 给出的路径读取当前人设包内的一个文字附件。只接受包内已登记的文本文件，二进制与超限文件会被拒绝。',
      parameters: {
        type: 'object',
        properties: {
          path: { type: 'string', description: '包内相对路径，例如 references/lantern.md' },
          personaId: { type: 'string', description: '人设 id；省略表示当前人设' },
        },
        required: ['path'],
        additionalProperties: false,
      },
      output: {
        schema: {
          type: 'object',
          properties: {
            personaId: { type: 'string' },
            path: { type: 'string' },
            text: { type: 'string' },
            error: { type: 'string' },
          },
          required: ['personaId', 'path'],
        },
        render: (_args, value) => value,
      },
      execute: args => {
        const result = resolve(args?.personaId);
        if (result.error !== undefined) return { error: result.error, path: '', personaId: '' };
        const entry = findEntry(result.entries, args?.path);
        if (entry === undefined) {
          return { personaId: result.id, path: String(args?.path ?? ''), error: '这个人设包里没有这个文件；先调用 list_persona_references 确认路径' };
        }
        if ((entry.bytes ?? 0) > MAX_TEXT_BYTES) {
          return { personaId: result.id, path: entry.path, error: '文件超过 256 KiB，拒绝一次读进对话' };
        }
        const loader = loaderOf?.();
        if (loader === undefined) {
          return { personaId: result.id, path: entry.path, error: '人设加载器未就绪' };
        }
        try {
          const text = loader.readText(result.id, entry.path);
          if (text === undefined) {
            return { personaId: result.id, path: entry.path, error: '读不到这个附件（可能不是文本文件）' };
          }
          return { personaId: result.id, path: entry.path, text };
        } catch (error) {
          log?.warn?.('读人设附件「%s/%s」失败：%s', result.id, entry.path, messageOf(error));
          return { personaId: result.id, path: entry.path, error: '读取失败，详见日志' };
        }
      },
    });

    // tools.register 自身返回随宿主 effect 撤销的 disposer；这里不再包一层
    // ctx.effect——那会在注册时立刻执行回调，把刚注册的工具又撤掉。
    void disposeList;
    void disposeRead;
  });
}
